import{aB as e,i as t,o,b3 as c}from"./chunks/framework.CJ7iKQOZ.js";const b=JSON.parse('{"title":"环境配置","description":"","frontmatter":{"title":"环境配置"},"headers":[],"relativePath":"base/config.md","filePath":"base/config.md"}'),a={name:"base/config.md"};function r(s,d,p,n,i,l){return o(),t("div",null,[...d[0]||(d[0]=[c('<h1 id="环境配置" tabindex="-1">环境配置 <a class="header-anchor" href="#环境配置" aria-label="Permalink to &quot;环境配置&quot;">​</a></h1><h2 id="开发环境" tabindex="-1">开发环境 <a class="header-anchor" href="#开发环境" aria-label="Permalink to &quot;开发环境&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>名称</th><th>版本</th></tr></thead><tbody><tr><td>Node.js</td><td>本地见 <code>.nvmrc</code>（<code>v24.15.0</code>），CI 使用 20.x</td></tr><tr><td>pnpm</td><td>CI 使用 v10</td></tr></tbody></table></div><p>依赖版本统一由 <code>pnpm-workspace.yaml</code> 的 <code>catalog</code> 维护。新增依赖时优先写入 <code>catalog</code>，再在包内用 <code>catalog:</code> 引用，避免各包版本漂移。</p><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><p>仓库是一个 <code>pnpm</code> workspace：</p><div class="vp-table"><table><thead><tr><th>包</th><th>名称</th><th>说明</th></tr></thead><tbody><tr><td><code>packages/core</code></td><td><code>@sepveneto/dnde-core</code></td><td>编辑器底层逻辑与类型，不依赖具体技术栈</td></tr><tr><td><code>packages/editor</code></td><td><code>@sepveneto/dnde</code></td><td>编辑器本体（消费者），打包为 <code>web components</code></td></tr><tr><td><code>packages/widgets</code></td><td><code>mpd-widgets</code></td><td>生产者示例，通过模块联邦暴露视图与配置</td></tr><tr><td><code>packages/plugins</code></td><td><code>@sepveneto/dnd-plugins</code></td><td>Rsbuild / Rspack 构建插件，负责 <code>shadow dom</code> 下的样式与缓存处理</td></tr><tr><td><code>docs</code></td><td><code>@sepveneto/dnd-docs</code></td><td>说明文档（VitePress）</td></tr></tbody></table></div><h2 id="常用脚本" tabindex="-1">常用脚本 <a class="header-anchor" href="#常用脚本" aria-label="Permalink to &quot;常用脚本&quot;">​</a></h2><p>在仓库根目录执行：</p><div class="vp-table"><table><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>pnpm bootstrap</code></td><td>依次构建 <code>core</code> → <code>plugins</code> → <code>editor</code></td></tr><tr><td><code>pnpm build:core</code></td><td>构建 <code>@sepveneto/dnde-core</code></td></tr><tr><td><code>pnpm build:plugin</code></td><td>构建 <code>@sepveneto/dnd-plugins</code></td></tr><tr><td><code>pnpm build:editor</code></td><td>构建 <code>@sepveneto/dnde</code></td></tr><tr><td><code>pnpm dev</code></td><td>启动编辑器 playground（<code>packages/editor</code>）</td></tr><tr><td><code>pnpm -C packages/widgets dev</code></td><td>启动生产者示例（默认端口 <code>8090</code>）</td></tr><tr><td><code>pnpm docs:dev</code></td><td>启动文档站点</td></tr><tr><td><code>pnpm docs:build</code></td><td>构建文档站点</td></tr></tbody></table></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>packages/editor</code> 与 <code>packages/widgets</code> 都通过 <code>@sepveneto/dnde-core</code> 的构建产物（<code>dist</code>）解析类型与运行时。改动 <code>packages/core</code> 后需要先执行 <code>pnpm build:core</code>（<code>pnpm bootstrap</code> 已包含该步骤），否则下游包可能读到过期的 <code>dist</code>，出现类型报错或运行时不一致。</p></div><h2 id="发布" tabindex="-1">发布 <a class="header-anchor" href="#发布" aria-label="Permalink to &quot;发布&quot;">​</a></h2><p><code>core</code>、<code>editor</code>、<code>plugins</code> 分别通过 <code>bumpp</code> 打 tag（<code>core@</code>、<code>editor@</code>、<code>plugin@</code>）触发对应的 GitHub Actions 工作流发布到 npm，详见 <code>.github/workflows/</code> 与 <code>scripts/</code>。</p>',13)])])}const m=e(a,[["render",r]]);export{b as __pageData,m as default};
